    public function __construct(){ add_action('wp_enqueue_scripts',[$this,'register_assets']); add_action('rest_api_init',[$this,'register_rest_routes']); add_shortcode('sc_personal_research_environment',[$this,'shortcode']); add_filter('sc_library_personal_research_environment_state',[$this,'filter_state'],10,3); }
