    public function register_rest_routes(){ register_rest_route(self::REST_NAMESPACE,self::REST_ROUTE,['methods'=>WP_REST_Server::READABLE,'permission_callback'=>[$this,'rest_signed_in'],'callback'=>[$this,'rest_state'],'args'=>['project_id'=>['sanitize_callback'=>'absint','default'=>0]]]); }
