    private static function context_project_id($context){ return is_array($context)?absint($context['project_id']??0):0; }
    private static function recent(array $items){ usort($items,static fn($a,$b)=>strcmp((string)($b['updated_at']??''),(string)($a['updated_at']??''))); return array_slice($items,0,8); }
    public static function state_for_user($uid,$selected=0){
        $uid=absint($uid); if(!$uid)return new WP_Error('sc_research_home_signin',__('Sign in to open your personal research environment.','sustainable-catalyst-library'),['status'=>401]);
        $project_ids=class_exists('SC_Library_Unified_Research_Projects_Source_Bundles')?SC_Library_Unified_Research_Projects_Source_Bundles::projects_for_user($uid):[]; $projects=[]; $recent=[];
        foreach($project_ids as $pid){$s=SC_Library_Unified_Research_Projects_Source_Bundles::project_state($pid,$uid);if(is_wp_error($s))continue;$x=['project_id'=>absint($pid),'title'=>self::title($s['title']??'',sprintf(__('Project %d','sustainable-catalyst-library'),$pid)),'status'=>sanitize_key((string)($s['status']??'active')),'reference_count'=>absint($s['reference_count']??0),'bundle_count'=>absint($s['bundle_count']??0),'modified_gmt'=>(string)($s['modified_gmt']??''),'urn'=>(string)($s['project_identity']['urn']??'')];$projects[]=$x;$recent[]=['kind'=>'project','label'=>__('Research Project','sustainable-catalyst-library'),'title'=>$x['title'],'project_id'=>absint($pid),'updated_at'=>$x['modified_gmt'],'target'=>'#research-projects'];}
        $selected=absint($selected);$owned=array_map('absint',$project_ids);if($selected&&!in_array($selected,$owned,true))$selected=0;if(!$selected&&$projects)$selected=absint($projects[0]['project_id']);
        $items=class_exists('SC_Library_Personal_Collections_Recommendations')?SC_Library_Personal_Collections_Recommendations::items_for_user($uid):[];$collections=class_exists('SC_Library_Personal_Collections_Recommendations')?SC_Library_Personal_Collections_Recommendations::collections_for_user($uid):[];$continuity=class_exists('SC_Library_Saved_Searches_Watchlists_Queue')?SC_Library_Saved_Searches_Watchlists_Queue::state_for_user($uid):[];
        $notebooks=[];$nids=class_exists('SC_Library_Reading_Notebook_Annotations')?SC_Library_Reading_Notebook_Annotations::notebooks_for_user($uid):[];foreach($nids as $nid){$s=SC_Library_Reading_Notebook_Annotations::notebook_state($nid,$uid);if(is_wp_error($s))continue;$pid=self::context_project_id($s['project_context']??[]);$x=['notebook_id'=>absint($nid),'title'=>self::title($s['title']??'',__('Reading notebook','sustainable-catalyst-library')),'project_id'=>$pid,'note_count'=>absint($s['note_count']??0),'annotation_count'=>absint($s['annotation_count']??0),'updated_at'=>(string)($s['updated_at']??''),'urn'=>(string)($s['urn']??'')];$notebooks[]=$x;$recent[]=['kind'=>'notebook','label'=>__('Reading Notebook','sustainable-catalyst-library'),'title'=>$x['title'],'project_id'=>$pid,'updated_at'=>$x['updated_at'],'target'=>'#reading-notebooks'];}
        $matrices=[];$mids=class_exists('SC_Library_Evidence_Matrix_Claim_Intelligence')?SC_Library_Evidence_Matrix_Claim_Intelligence::matrices_for_user($uid):[];foreach($mids as $mid){$s=SC_Library_Evidence_Matrix_Claim_Intelligence::matrix_state($mid,$uid);if(is_wp_error($s))continue;$pid=self::context_project_id($s['project_context']??[]);$x=['matrix_id'=>absint($mid),'title'=>self::title($s['title']??'',__('Evidence matrix','sustainable-catalyst-library')),'project_id'=>$pid,'claim_count'=>absint($s['claim_count']??0),'evidence_link_count'=>absint($s['evidence_link_count']??0),'updated_at'=>(string)($s['updated_at']??''),'urn'=>(string)($s['urn']??'')];$matrices[]=$x;$recent[]=['kind'=>'matrix','label'=>__('Evidence Matrix','sustainable-catalyst-library'),'title'=>$x['title'],'project_id'=>$pid,'updated_at'=>$x['updated_at'],'target'=>'#evidence-matrix'];}
        $routes=self::learning_routes($uid);foreach($routes as $r){$recent[]=['kind'=>'learning_route','label'=>__('Learning Route','sustainable-catalyst-library'),'title'=>self::title($r['title']??'',__('Learning route','sustainable-catalyst-library')),'project_id'=>absint($r['project_id']??0),'updated_at'=>(string)($r['updated_at']??$r['created_at']??''),'target'=>'#open-learning-ii'];}
        $project=null;if($selected&&class_exists('SC_Library_Unified_Research_Projects_Source_Bundles')){$s=SC_Library_Unified_Research_Projects_Source_Bundles::project_state($selected,$uid);if(!is_wp_error($s)){$project=['project_id'=>$selected,'title'=>self::title($s['title']??'',__('Research project','sustainable-catalyst-library')),'status'=>sanitize_key((string)($s['status']??'active')),'research_question'=>sanitize_textarea_field((string)($s['research_question']??'')),'reference_count'=>absint($s['reference_count']??0),'bundle_count'=>absint($s['bundle_count']??0),'urn'=>(string)($s['project_identity']['urn']??''),'notebooks'=>array_values(array_filter($notebooks,static fn($n)=>absint($n['project_id']??0)===$selected)),'matrices'=>array_values(array_filter($matrices,static fn($m)=>absint($m['project_id']??0)===$selected)),'learning_routes'=>array_values(array_filter($routes,static fn($r)=>absint($r['project_id']??0)===$selected))];$project['notebook_count']=count($project['notebooks']);$project['matrix_count']=count($project['matrices']);$project['learning_route_count']=count($project['learning_routes']);}}
        $out=['schema'=>self::SCHEMA,'version'=>self::VERSION,'visibility'=>'private','user_id'=>$uid,'generated_at'=>gmdate('c'),'counts'=>['projects'=>count($projects),'personal_items'=>count($items),'personal_collections'=>count($collections),'saved_searches'=>count((array)($continuity['saved_searches']??[])),'watchlists'=>count((array)($continuity['watchlists']??[])),'research_queue'=>count((array)($continuity['research_queue']??[])),'reading_notebooks'=>count($notebooks),'evidence_matrices'=>count($matrices),'learning_routes'=>count($routes)],'projects'=>$projects,'selected_project_id'=>$selected,'selected_project'=>$project,'recent_activity'=>self::recent($recent),'contract'=>self::contract()];return apply_filters('sc_library_personal_research_environment_state_payload',$out,$uid,$selected);
    }
    public function filter_state($state,$uid,$project_id=0){$x=self::state_for_user(absint($uid),absint($project_id));return is_wp_error($x)?$state:$x;}
    private static function canonical(){return class_exists('SC_Library_Canonical_Route_Identity')?SC_Library_Canonical_Route_Identity::canonical_url():home_url('/knowledge-libraries/');}
    private static function project_url($pid,$fragment){return add_query_arg('sc_project',absint($pid),self::canonical()).$fragment;}
