<?php else:$counts=(array)($state['counts']??[]);$projects=(array)($state['projects']??[]);$project=is_array($state['selected_project']??null)?$state['selected_project']:null;$metrics=['projects'=>__('Projects','sustainable-catalyst-library'),'personal_items'=>__('My Library','sustainable-catalyst-library'),'saved_searches'=>__('Saved searches','sustainable-catalyst-library'),'watchlists'=>__('Watchlists','sustainable-catalyst-library'),'research_queue'=>__('Research queue','sustainable-catalyst-library'),'reading_notebooks'=>__('Notebooks','sustainable-catalyst-library'),'evidence_matrices'=>__('Evidence matrices','sustainable-catalyst-library'),'learning_routes'=>__('Learning routes','sustainable-catalyst-library')]; ?>
